from pathlib import Path
from datetime import datetime
import json,hashlib,re
import pandas as pd
root=Path.cwd();e7=root/'reports/research/510300_cftc_treasury_position_source_qualification_v1';e8=root/'reports/research/510300_fed_reserve_causes_single_release_v1'
def read(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
r7=read(e7/'result.json');r8=read(e8/'result.json');f7=read(e7/'freeze.json');f8=read(e8/'freeze.json')
receipts=read(e7/'background_source_receipts.json')+read(e7/'archive_schema_delay_receipts.json')
checks={}
checks['all_six_original_source_hashes']=all(x['status']=='FETCHED' and sha(e7/x['file'])==x['sha256'] for x in receipts) and sha(e8/read(e8/'source_receipt.json')['file'])==read(e8/'source_receipt.json')['sha256']
checks['registered_protocols_and_parent_inputs']=sha(e7/'protocol.json')==f7['protocol_sha256'] and sha(e8/'protocol.json')==f8['protocol_sha256'] and all(sha(root/rel)==h for rel,h in f7['input_hashes'].items())
weekly=pd.read_parquet(e7/'原10年合约52周字段与时钟资格.parquet')
delays=pd.read_csv(e7/'7次实际迟报公布对齐.csv')
checks['saved_e7_counts_and_partial_clock']=len(weekly)==52 and len(delays)==7 and weekly.supported_available_at_upper_bound.notna().sum()==7 and not r7['strict_source_gate_passed']
checks['e7_failed_source_is_not_strategy_rejection']=r7['score_status'].startswith('NOT_RUN') and not r7['candidate_single_field_computed'] and r7['new_fits']==0 and not r7['equity_returns_loaded']
components=pd.read_csv(e8/'准备金周变化完整原因构成.csv')
checks['e8_complete_saved_cause_bridge']=int(components.reserve_contribution_million_usd.sum())==r8['reserve_weekly_average_change_million_usd']==28168 and r8['supply_weekly_average_change_million_usd']-r8['absorbing_weekly_average_change_million_usd']==28168
checks['both_results_are_fact_or_source_only']=all(x['new_fits']==0 and x['new_accounts']==0 and x['new_repository_code_edits']==0 and not x['goal_achieved'] and not x['orders_authorized'] for x in [r7,r8])
checks['e9_proposal_not_run']=read(e8/'next_experiment.json')['new_fits']==0 and read(e8/'next_experiment.json')['requires_registration']
checks['e6_rejection_preserved']=read(root/'reports/research/510300_multidim_treasury_long_supply_cause_score_v1/result.json')['status']=='REJECTED_FROZEN_LONG_SUPPLY_INCREMENT_NOT_ESTABLISHED'
keys_by_config={
 'config/510300_historical_cause_discovery_v1.json':['target_net_sharpe','target_net_cagr','target_max_drawdown','research_mode','executable_assets','new_prospective_forecasts_enabled','orders_authorized'],
 'config/510300_existing_data_training_mandate_v1.json':['capital_cny','target_net_sharpe','target_net_cagr','target_max_drawdown','account_tail_risk_contract','minimum_complete_cycles_each_full_calendar_year','executable_assets','minute_data_research_enabled','scheduled_pcf_iopv_collection','orders_authorized']}
checks['targets_risk_and_authority_unchanged']=all(all(read(root/rel).get(k)==f7['authority_config_snapshots'][rel].get(k) for k in keys) for rel,keys in keys_by_config.items())
missing=[];count=0
for name in ['docs/PROJECT_STATE.md','docs/RESEARCH_DECISIONS.md']:
 for target in re.findall(r'\]\(([^)]+)\)',(root/name).read_text(encoding='utf-8')):
  if not any(x in target for x in ['510300_cftc_treasury_position_source_qualification_v1','510300_fed_reserve_causes_single_release_v1']):continue
  count+=1
  if not ((root/name).parent/target).is_file():missing.append(target)
checks['new_long_term_fact_links_exist']=not missing
assert all(checks.values()),checks
common={'checked_at':datetime.now().astimezone().isoformat(),'status':'PASS_SAVED_SOURCE_CLOCK_AND_CAUSE_IDENTITY_RECOMPUTATION',
 'checks':checks,'document_links_checked':count,'new_model_fits_in_check':0,'new_accounts_in_check':0,
 'historical_first_vintage_verified':False,'independent_financial_validation':False,'goal_achieved':False}
for D in [e7,e8]:
 (D/'必要保存输出核对.json').write_text(json.dumps(common,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
print(json.dumps(common,ensure_ascii=False,indent=2))
for name in ['docs/PROJECT_STATE.md','docs/RESEARCH_DECISIONS.md']:
 for i,line in enumerate((root/name).read_text(encoding='utf-8').splitlines(),1):
  if line.startswith('### 5.8') or line.startswith('### R65｜') or line.startswith('### R66｜') or line.startswith('### E9：'):print(name,i,line)
